import { Hono } from 'hono'

export type Task = {
  id: number
  title: string
  done: boolean
  createdAt: string
  updatedAt: string
}

type ParsedBody =
  | { ok: true; body: Record<string, unknown> }
  | { ok: false; error: string }

const MAX_TITLE_LENGTH = 500

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const parseJsonObject = async (req: Request): Promise<ParsedBody> => {
  let body: unknown
  try {
    body = await req.json()
  } catch {
    return { ok: false, error: 'Request body must be valid JSON' }
  }
  if (!isPlainObject(body)) {
    return { ok: false, error: 'Request body must be a JSON object' }
  }
  return { ok: true, body }
}

// Returns an error message, or null if the title is acceptable.
const validateTitle = (title: unknown): string | null => {
  if (typeof title !== 'string') return '"title" must be a string'
  if (title.trim().length === 0) return '"title" must not be empty'
  if (title.length > MAX_TITLE_LENGTH) {
    return `"title" must be at most ${MAX_TITLE_LENGTH} characters`
  }
  return null
}

const parseId = (raw: string): number | null => {
  if (!/^\d+$/.test(raw)) return null
  const id = Number(raw)
  return Number.isSafeInteger(id) ? id : null
}

/**
 * Builds a fresh app instance with its own in-memory task store.
 * Each call is fully isolated, which keeps tests independent of one another.
 */
export const createApp = () => {
  const app = new Hono()
  const tasks = new Map<number, Task>()
  let nextId = 1

  app.get('/', (c) => {
    return c.text('Hello Hono!')
  })

  app.post('/tasks', async (c) => {
    const parsed = await parseJsonObject(c.req.raw)
    if (!parsed.ok) return c.json({ error: parsed.error }, 400)

    const { title, done } = parsed.body

    if (title === undefined) return c.json({ error: '"title" is required' }, 400)
    const titleError = validateTitle(title)
    if (titleError) return c.json({ error: titleError }, 400)

    if (done !== undefined && typeof done !== 'boolean') {
      return c.json({ error: '"done" must be a boolean' }, 400)
    }

    const now = new Date().toISOString()
    const task: Task = {
      id: nextId++,
      title: (title as string).trim(),
      done: done ?? false,
      createdAt: now,
      updatedAt: now,
    }
    tasks.set(task.id, task)

    c.header('Location', `/tasks/${task.id}`)
    return c.json(task, 201)
  })

  app.get('/tasks', (c) => {
    return c.json([...tasks.values()])
  })

  app.get('/tasks/:id', (c) => {
    const id = parseId(c.req.param('id'))
    const task = id === null ? undefined : tasks.get(id)
    if (!task) return c.json({ error: 'Task not found' }, 404)
    return c.json(task)
  })

  app.patch('/tasks/:id', async (c) => {
    const id = parseId(c.req.param('id'))
    const task = id === null ? undefined : tasks.get(id)
    if (!task) return c.json({ error: 'Task not found' }, 404)

    const parsed = await parseJsonObject(c.req.raw)
    if (!parsed.ok) return c.json({ error: parsed.error }, 400)

    const { title, done } = parsed.body

    if (title === undefined && done === undefined) {
      return c.json(
        { error: 'Request body must include "title" and/or "done"' },
        400,
      )
    }
    if (title !== undefined) {
      const titleError = validateTitle(title)
      if (titleError) return c.json({ error: titleError }, 400)
    }
    if (done !== undefined && typeof done !== 'boolean') {
      return c.json({ error: '"done" must be a boolean' }, 400)
    }

    const updated: Task = {
      ...task,
      title: title !== undefined ? (title as string).trim() : task.title,
      done: done !== undefined ? done : task.done,
      updatedAt: new Date().toISOString(),
    }
    tasks.set(updated.id, updated)

    return c.json(updated)
  })

  app.delete('/tasks/:id', (c) => {
    const id = parseId(c.req.param('id'))
    if (id === null || !tasks.has(id)) {
      return c.json({ error: 'Task not found' }, 404)
    }
    tasks.delete(id)
    return c.body(null, 204)
  })

  return app
}

import { createApp } from './app'

const app = createApp()

export default app
